styles.h1:
font-size: 28px;
color: #00e6ff;
margin-bottom: 15px;
letter-spacing: 1px;
font-weight: 600;

text-shadow: 0 0 10px rgba(0, 230, 255, 0.5);
position: relative;
padding-bottom: 10px;

styles.h2:
font-size: 16px;
color: #7fdbff;
margin-bottom: 24px;
font-weight: 400;
letter-spacing: 1px;

opacity: 0.8;

styles.h3:
display: block;
color: #00e6ff;
margin-bottom: 6px;
font-size: 16px;
font-weight: 600;
letter-spacing: 0.5px;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #00e6ff;
text-decoration: none;
border-bottom: 1px dashed rgba(0, 230, 255, 0.5);
transition: all 0.3s ease;
position: relative;

styles.ol:
list-style: none;
padding: 0.5em 3.5em;
counter-reset: decorated-counter;
margin-bottom: 1.5em;

styles.li:
position: relative;


margin-bottom: 16px;
padding-left: 40px;
color: #a4b1cd;
line-height: 1.6;
font-size: 14px;

styles.blockquote:
background: rgba(0, 0, 0, 0.2);
border-left: 3px solid #00e6ff;
color: #7fdbff;
padding: 15px 20px;
margin: 20px 0;
font-style: italic;
position: relative;
border-radius: 0 4px 4px 0;

styles.pre:
background: rgba(0, 0, 0, 0.3);
border: 1px solid rgba(0, 230, 255, 0.2);
border-radius: 4px;
padding: 15px;
overflow-x: auto;
position: relative;

styles.hr:
border: 0;
height: 1px;
background: linear-gradient(90deg, transparent, #00e6ff, transparent);
margin: 25px 0;
opacity: 0.5;

styles.img:
max-width: 100%;
border: 1px solid rgba(0, 230, 255, 0.3);
border-radius: 4px;
box-shadow:
  0 0 15px rgba(0, 0, 0, 0.5),
  0 0 5px rgba(0, 230, 255, 0.2);
margin: 20px auto;

styles.table:
width: 100%;
border-collapse: collapse;
margin: 20px 0;
background: rgba(15, 18, 24, 0.5);
border: 1px solid rgba(0, 230, 255, 0.2);
box-shadow: 0 0 10px rgba(0, 0, 0, 0.3);

styles.th:
background: rgba(0, 230, 255, 0.1);
color: #00e6ff;
border-bottom: 1px solid rgba(0, 230, 255, 0.2);
padding: 10px;
font-weight: 600;
text-align: left;

